-- ── story 4-1b: the client order number ──────────────────────────────────
-- Generated by drizzle-kit (the column and the two partial indexes) and
-- hand-amended around the generated part: the fail-fast guard, the shape
-- CHECK and the post-migration probe (drizzle-kit is blind to both; `bun run
-- db:generate` afterwards reports "No schema changes").
--
-- Additive: one nullable column with no default (no rewrite, no backfill —
-- every existing order reads `client_order_ref IS NULL`, which the CHECK and
-- both indexes admit). No foreign keys (IMPLEMENTATION-GUIDE §3).
--
-- `client_order_ref` is the client's own order number: 1–64 printable ASCII
-- characters with no space first or last (`orders_client_order_ref_shape_check`;
-- the command trims and refuses the same shape behind its replay lookup). It
-- is unique per client among LIVE orders — `orders_client_order_ref_live_unique`
-- is partial on `status <> 'cancelled'`, so a cancelled order frees its number
-- (cancel-and-re-create is the only way to fix an order). Because that index
-- leaves cancelled orders out, the `reference` search's client-number arm has
-- its own NON-unique `orders_client_order_ref_idx` (any status — code review
-- BH5). `orders_external_event_client_idx` serves the search's channel
-- arm (`external_event_id`), which `orders_source_event_unique` cannot — that
-- one leads with `integration_id`.
--
-- Lock cost: the ADD COLUMN takes a brief ACCESS EXCLUSIVE lock (no rewrite);
-- the ADD CONSTRAINT CHECK scans the table once under it; all three indexes are
-- built NON-concurrently (the 0081 precedent — the migrator runs every pending
-- migration in one transaction, where CONCURRENTLY is refused), each holding
-- a SHARE lock on `orders` while it builds. Accepted pre-launch; the live-deploy
-- runbook (build CONCURRENTLY by hand under the same name first) is in PENDING.

-- ── 0. fail-fast ─────────────────────────────────────────────────────────
DO $$
BEGIN
	IF EXISTS (
		SELECT 1 FROM information_schema.columns
		 WHERE table_schema = 'public' AND table_name = 'orders' AND column_name = 'client_order_ref'
	) THEN
		RAISE EXCEPTION 'migration 0088: orders.client_order_ref already exists — this migration has already been applied.';
	END IF;
END $$;
--> statement-breakpoint
ALTER TABLE "orders" ADD COLUMN "client_order_ref" text;--> statement-breakpoint
CREATE UNIQUE INDEX "orders_client_order_ref_live_unique" ON "orders" USING btree ("tenant_id","client_order_ref","client_id") WHERE client_order_ref is not null and status <> 'cancelled';--> statement-breakpoint
CREATE INDEX "orders_client_order_ref_idx" ON "orders" USING btree ("tenant_id","client_order_ref","client_id") WHERE client_order_ref is not null;--> statement-breakpoint
CREATE INDEX "orders_external_event_client_idx" ON "orders" USING btree ("tenant_id","external_event_id","client_id") WHERE external_event_id is not null;--> statement-breakpoint
-- ── hand-amended: the shape CHECK (migration SQL only) ────────────────────
-- 1–64 characters, each printable ASCII (0x20–0x7E), the first and the last
-- not a space (0x21–0x7E). `IS NULL OR` first: a NULL never reaches the regex
-- (guide §3 — a CHECK admits NULL, so the NULL arm is stated, not implied).
-- Mirrored by `CLIENT_ORDER_REF_RE` (src/modules/outbound/order.command.ts),
-- pinned against this CHECK by test/order-client-ref.spec.ts.
ALTER TABLE "orders" ADD CONSTRAINT "orders_client_order_ref_shape_check" CHECK (
	"client_order_ref" IS NULL OR "client_order_ref" ~ '^[!-~]([ -~]{0,62}[!-~])?$'
);--> statement-breakpoint
-- ── the post-migration assertion (the 0087 model) ─────────────────────────
-- Made-up uuids. The accepted shapes are inserted first and rolled back by a
-- sentinel exception, so a CHECK or index that refused everything fails the
-- migration; each refused shape runs in its own subtransaction and must be
-- refused BY ITS NAMED CONSTRAINT (guide §3).
DO $$
DECLARE
	t uuid := gen_random_uuid();
	w uuid := gen_random_uuid();
	c1 uuid := gen_random_uuid();
	c2 uuid := gen_random_uuid();
	refused_by text;
	expected text;
	probe text;
BEGIN
	-- (1) accepted shapes: no ref (every pre-4-1b order); one character; 64
	-- characters; an inner space and ASCII punctuation; the same ref for
	-- another client; the same ref on a cancelled order of the same client
	-- (a cancelled order frees its number) beside a live one; a channel order.
	BEGIN
		INSERT INTO "orders" ("id","tenant_id","client_id","warehouse_id","status","client_order_ref","external_event_id")
		VALUES
			(gen_random_uuid(), t, c1, w, 'accepted', NULL, NULL),
			(gen_random_uuid(), t, c1, w, 'accepted', 'A', NULL),
			(gen_random_uuid(), t, c1, w, 'accepted', 'S' || repeat('x', 62) || 'Z', NULL),
			(gen_random_uuid(), t, c1, w, 'accepted', 'SO 1042/B-7#~!', NULL),
			(gen_random_uuid(), t, c1, w, 'accepted', 'SO-1042', NULL),
			(gen_random_uuid(), t, c2, w, 'accepted', 'SO-1042', NULL),
			(gen_random_uuid(), t, c1, w, 'cancelled', 'SO-1042', NULL),
			(gen_random_uuid(), t, c1, w, 'cancelled', 'SO-1042', NULL),
			(gen_random_uuid(), t, c1, w, 'accepted', NULL, 'AMZ-9');
		RAISE EXCEPTION USING ERRCODE = 'P0088', MESSAGE = 'rollback the accepted probes';
	EXCEPTION
		WHEN check_violation OR unique_violation OR not_null_violation THEN
			RAISE EXCEPTION 'migration 0088: an accepted shape was refused (%).', SQLERRM;
		WHEN SQLSTATE 'P0088' THEN
			NULL;
	END;
	-- (2) refused shapes, each by its named constraint.
	FOREACH probe IN ARRAY ARRAY[
		'empty', '65 characters', 'control character', 'leading space', 'trailing space', 'non-ascii',
		'live duplicate', 'ready duplicate'
	] LOOP
		refused_by := NULL;
		expected := CASE
			WHEN probe IN ('live duplicate', 'ready duplicate') THEN 'orders_client_order_ref_live_unique'
			ELSE 'orders_client_order_ref_shape_check'
		END;
		BEGIN
			CASE probe
				WHEN 'empty' THEN
					INSERT INTO "orders" ("id","tenant_id","client_id","warehouse_id","client_order_ref")
					VALUES (gen_random_uuid(), t, c1, w, '');
				WHEN '65 characters' THEN
					INSERT INTO "orders" ("id","tenant_id","client_id","warehouse_id","client_order_ref")
					VALUES (gen_random_uuid(), t, c1, w, 'S' || repeat('x', 63) || 'Z');
				WHEN 'control character' THEN
					INSERT INTO "orders" ("id","tenant_id","client_id","warehouse_id","client_order_ref")
					VALUES (gen_random_uuid(), t, c1, w, E'SO\t1042');
				WHEN 'leading space' THEN
					INSERT INTO "orders" ("id","tenant_id","client_id","warehouse_id","client_order_ref")
					VALUES (gen_random_uuid(), t, c1, w, ' SO-1042');
				WHEN 'trailing space' THEN
					INSERT INTO "orders" ("id","tenant_id","client_id","warehouse_id","client_order_ref")
					VALUES (gen_random_uuid(), t, c1, w, 'SO-1042 ');
				WHEN 'non-ascii' THEN
					INSERT INTO "orders" ("id","tenant_id","client_id","warehouse_id","client_order_ref")
					VALUES (gen_random_uuid(), t, c1, w, 'SO-' || chr(233));
				WHEN 'live duplicate' THEN
					INSERT INTO "orders" ("id","tenant_id","client_id","warehouse_id","status","client_order_ref")
					VALUES (gen_random_uuid(), t, c1, w, 'accepted', 'DUP-1'), (gen_random_uuid(), t, c1, w, 'accepted', 'DUP-1');
				WHEN 'ready duplicate' THEN
					-- any live arm counts, not only `accepted`
					INSERT INTO "orders" ("id","tenant_id","client_id","warehouse_id","status","client_order_ref")
					VALUES (gen_random_uuid(), t, c1, w, 'dispatched', 'DUP-2'), (gen_random_uuid(), t, c1, w, 'ready_to_dispatch', 'DUP-2');
			END CASE;
		EXCEPTION
			WHEN check_violation OR unique_violation THEN
				GET STACKED DIAGNOSTICS refused_by = CONSTRAINT_NAME;
		END;
		IF refused_by IS DISTINCT FROM expected THEN
			RAISE EXCEPTION 'migration 0088: probe "%" was refused by % (expected %).', probe, coalesce(refused_by, 'nothing'), expected;
		END IF;
	END LOOP;
	IF EXISTS (SELECT 1 FROM "orders" WHERE "tenant_id" = t) THEN
		RAISE EXCEPTION 'migration 0088: a probe row survived.';
	END IF;
END $$;
